    public static void testTheLinesTheStrokesMadeAreNotThePagesText() {
        emon.Port.Cells cand = emon.Port.newCells();
        emon.Port.Cells ow = emon.Port.newCells();
        emon.Port.Cells ol = emon.Port.newCells();
        emon.Port.Cells scr = emon.Port.newCells();
        while (emon.Port.cellsLen(cand) < Sigpx.spW()) {
            emon.Port.cellsPush(cand, 0);
        }
        emon.Port.cellsSet(cand, 0, 3);
        emon.Port.cellsSet(cand, 2, 1000);
        emon.Port.cellsSet(cand, 3, 1000);
        emon.Port.cellsSet(cand, 4, 7000);
        emon.Port.cellsSet(cand, 5, 4000);
        // line 1: two words inside, the engine 300 sure (the strokes read as letters); line 2: one word inside at 900 (a typed name under the strokes); line 3: elsewhere
        Evidence.owNew(ow, 1, 1500, 1500, 3000, 2500, 1500, 2500, 3000, 2500, 0, 0, 0, 1, 0, 300, -1);
        Evidence.owNew(ow, 1, 3500, 1500, 5000, 2500, 3500, 2500, 5000, 2500, 0, 0, 0, 1, 0, 300, -1);
        Evidence.owNew(ow, 1, 2000, 3000, 4000, 3800, 2000, 3800, 4000, 3800, 0, 0, 0, 1, 0, 900, -1);
        Evidence.owNew(ow, 1, 30000, 30000, 32000, 31000, 30000, 31000, 32000, 31000, 0, 0, 0, 1, 0, 900, -1);
        Evidence.olNew(ol, 1, 1500, 1500, 5000, 2500, 1500, 2500, 5000, 2500, 0, 0, 0, 2);
        Evidence.olNew(ol, 1, 2000, 3000, 4000, 3800, 2000, 3800, 4000, 3800, 0, 0, 2, 1);
        Evidence.olNew(ol, 1, 30000, 30000, 32000, 31000, 30000, 31000, 32000, 31000, 0, 0, 3, 1);
        while (emon.Port.cellsLen(scr) < (Scan.scSelBase() + 8)) {
            emon.Port.cellsPush(scr, 0);
        }
        emon.Port.cellsSet(scr, Scan.scSelBase(), 0);
        emon.Port.cellsSet(scr, Scan.scSelBase() + 1, 1);
        emon.Port.cellsSet(scr, Scan.scSelBase() + 2, 2);
        emon.Testport.assertEq(Sigpx.spDropLines(scr, 3, ol, ow, cand), 2, "the strokes' line is out; the typed name the engine is sure of and the line elsewhere stay");
        emon.Testport.assertEq(emon.Port.cellsAt(scr, Scan.scSelBase()), 1, "the typed name first");
        emon.Testport.assertEq(emon.Port.cellsAt(scr, Scan.scSelBase() + 1), 2, "then the other");
    }
